    const data = await v2PublicService(c).cityList(c.req.query("address"));
    return data === null
      ? jsonFail(c, "地址暂未录入，请联系管理员")
      : jsonOk(c, data);
  } catch (error) {
    if (error instanceof ValidateException) return jsonFail(c, error.message);
    throw error;
  }
}

