  return methods.length > 0
    && methods.every(method => ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'].includes(method))
    && methods.every(method => !requiredAdminPermission(method, menu.apiUrl));
}

