    if (hasAdminPermission(keys, 'system.legacy_role_view')) menus.push({
      id: 20_002, pid: 0, path: '/system/legacy-roles', name: '下一层级角色',
      icon: '', sort: 0, type: 1, children: [],
    });
    return menus;
  }

