import {readExpressPredecessor as readFileSync} from './helpers/parameterSourceBinding';
import {createHash} from 'node:crypto';
import {resolve} from 'node:path';
import {describe,expect,it} from 'vitest';
import {buildExpressPredecessorApiAuditReport as buildAdminFrontendApiAuditReport} from './helpers/parameterSourceBinding';
import {platformMenuSourceBinding as proof,reversePlatformMenuSource,readPlatformMenuPredecessor,readAdminProfilePredecessor,buildPlatformMenuPredecessorApiAuditReport} from './helpers/parameterSourceBinding';
import {adminProfileSourceBinding,reverseAdminProfileSource} from './helpers/adminProfileSourceBinding';
import {PLATFORM_MENU_FIELDS,PLATFORM_MENU_ICONS} from '../../view/common/platformMenuRules';
const root=resolve(import.meta.dirname,'../..'),read=(f:string)=>readFileSync(resolve(root,f),'utf8'),sha=(v:string|Uint8Array)=>createHash('sha256').update(v).digest('hex');
describe('platform type1 full PHP evidence, exact additive source binding and preserved predecessors',()=>{
 for(const row of proof.sources){
  it(`pins exact actual producer and predecessor ${row.file}`,()=>{const actual=read(row.file);expect(sha(actual)).toBe(row.after_sha256);expect(sha(reversePlatformMenuSource(row.file,actual))).toBe(row.before_sha256);expect(sha(readPlatformMenuPredecessor(resolve(root,row.file)))).toBe(row.before_sha256);});
  it(`rejects complete-source truncation, append, duplication and forged mapping ${row.file}`,()=>{const actual=read(row.file);for(const bad of [actual.slice(1),actual+'\n// unreviewed\n',actual+actual])expect(()=>reversePlatformMenuSource(row.file,bad)).toThrow();for(const key of ['before_sha256','after_sha256']as const){const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)![key]='0'.repeat(64);expect(()=>reversePlatformMenuSource(row.file,actual,forged)).toThrow();}const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)!.edits[0]!.after_line=2;expect(()=>reversePlatformMenuSource(row.file,actual,forged)).toThrow();});
  if(row.file.startsWith('workers-ts/test/'))it(`keeps every predecessor assertion and negative fixture ${row.file}`,()=>{const strip=(s:string)=>s.replace(/^import[\s\S]*?;\n/gmu,'');expect(strip(row.edits[0]!.after_source)).toBe(strip(row.edits[0]!.before_source));});
 }
 for(const row of proof.full_additions)it(`pins complete new source ${row.file}`,()=>{const raw=readFileSync(resolve(root,row.file));expect(raw.byteLength).toBe(row.bytes);expect(sha(raw)).toBe(row.sha256);});
 for(const row of proof.PHP_sources)it(`pins full original fixed PHP source ${row.file}`,()=>{expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');expect(sha(row.raw_utf8)).toBe(row.sha256);expect(new TextEncoder().encode(row.raw_utf8).byteLength).toBe(row.bytes);});
 const frozen=Object.entries(proof.frozen_predecessor_evidence);
 for(let start=0;start<frozen.length;start+=64)it(`keeps accepted dated evidence bytes ${start+1}..${Math.min(start+64,frozen.length)}`,()=>{for(const[file,hash]of frozen.slice(start,start+64))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});
 it('keeps the original auth, runtime boundaries, authority writer, type4 capability and whole-shop stage plan unchanged',()=>{for(const[file,hash]of Object.entries(proof.observed_unchanged))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});
 it('rebuilds real current API inventory with exactly six new calls and zero gaps',()=>{const report=buildAdminFrontendApiAuditReport(),raw=read(proof.current_report.file);expect(JSON.stringify(report,null,2)+'\n').toBe(raw);expect(sha(raw)).toBe(proof.current_report.sha256);expect(report.counts).toEqual({callSites:723,pathVariants:761,registered:761,executable:761,controlledUnavailable:0,unregistered:0,unresolved:0});const previous=buildPlatformMenuPredecessorApiAuditReport();for(const call of previous.calls)expect(report.calls).toContainEqual(call);expect(report.calls.filter(call=>call.source==='view/admin-ts/src/api/platformMenus.ts')).toHaveLength(6);});
 it('composes current -> platform menu -> accepted profile without changing earlier helper bytes',()=>{for(const f of ['view/admin-ts/src/router/index.ts','workers-ts/src/routes/adminapi.ts','workers-ts/src/migrations/auditRuntimeBusinessPrivileges.ts','.github/workflows/workers-runtime-linux.yml']){const prior=reversePlatformMenuSource(f,read(f));expect(readPlatformMenuPredecessor(resolve(root,f),'utf8')).toBe(prior);expect(readAdminProfilePredecessor(resolve(root,f),'utf8')).toBe(reverseAdminProfileSource(f,prior));}expect(sha(proof.previous_report.raw_utf8)).toBe(adminProfileSourceBinding.current_report.sha256);});
 it('carries the full original static icon directory and exactly eleven active author fields',()=>{expect(PLATFORM_MENU_FIELDS).toEqual(['pid','auth_type','menu_name','menu_path','unique_auth','api_url','methods','icon','sort','is_show','is_show_path']);const icon=proof.PHP_sources.find(r=>r.file==='view/admin/src/utils/icon.js')!;const tokens=Array.from(icon.raw_utf8.matchAll(/\{\s*type:\s*"([^"]+)"\s*\}/gu),m=>m[1]);expect(tokens).toHaveLength(860);expect(PLATFORM_MENU_ICONS).toEqual(['',...tokens]);expect(proof.boundaries.icons).toContain('zero image slots');});
 it('retains fixed navigation, exact legacy alias and explicit frontend CI validation',()=>{const router=read('view/admin-ts/src/router/index.ts');expect(router).toContain('alias: "/admin/setting/system_menus/index"');expect(router).toContain('import("@/pages/system/PlatformMenuRules.vue")');expect(read('.github/workflows/workers-runtime-linux.yml')).toContain('npm run test:platform-menu-rules');expect(JSON.parse(read('view/admin-ts/package.json')).scripts['test:platform-menu-rules']).toContain('--test-concurrency=1');expect(proof.boundaries.navigation).toContain('never loads arbitrary components');});
});

