 for(const entry of proof.sources){
  it(`pins complete actual source and complete predecessor ${entry.file}`,()=>{const current=read(entry.file);expect(sha(current)).toBe(entry.after_sha256);expect(sha(reverseErrorPagesSource(entry.file,current))).toBe(entry.before_sha256);expect(sha(readErrorPagesPredecessor(resolve(root,entry.file)))).toBe(entry.before_sha256);expect(readErrorPagesPredecessor(resolve(root,entry.file),'utf8')).toBe(entry.edits[0]!.before_source);});
  it(`rejects unreviewed, truncated and duplicated source ${entry.file}`,()=>{const raw=read(entry.file);for(const value of [raw+'\n// unreviewed\n',raw.slice(1),raw+raw])expect(()=>reverseErrorPagesSource(entry.file,value)).toThrow();});
  for(const field of ['before_sha256','after_sha256','after_line']as const)it(`rejects forged ${field} ${entry.file}`,()=>{const changed=structuredClone(proof),row=changed.sources.find(r=>r.file===entry.file)!;if(field==='after_line')row.edits[0]!.after_line=2;else row[field]='0'.repeat(64);expect(()=>reverseErrorPagesSource(entry.file,read(entry.file),changed)).toThrow();});
 }
 for(const entry of proof.full_additions)it(`pins complete actual producer or runtime suite ${entry.file}`,()=>expect(sha(read(entry.file))).toBe(entry.sha256));
