 for(const entry of proof.PHP_evidence)it(`pins actual behavior lines ${entry.source}:${entry.start}`,()=>{const source=proof.PHP_sources.find(row=>row.file===entry.source)!;expect(source.raw_utf8.split(/(?<=\n)/u).slice(entry.start-1,entry.end).join('')).toBe(entry.fragment);expect(sha(entry.fragment)).toBe(entry.fragment_sha256);});
 it('retains the exact deterministic API inventory: zero new calls or Worker routes',()=>{const raw=read(proof.current_report.file),report=JSON.parse(raw);expect(sha(raw)).toBe(proof.current_report.sha256);expect(proof.current_report.sha256).toBe('e00f364f4b64fd6eeb308a171bfdd6a0dcfe1e9ea498f359a4151921da8efec3');expect(buildAdminFrontendApiAuditReport()).toEqual(report);expect(report.counts).toEqual({callSites:709,pathVariants:747,registered:747,executable:747,controlledUnavailable:0,unregistered:0,unresolved:0});});
 it('composes all exact current-to-browser-to-config predecessor layers',()=>{for(const file of ['view/admin-ts/src/router/index.ts','.github/workflows/workers-runtime-linux.yml']){const outer=reverseErrorPagesSource(file,read(file)),browser=reverseBrowserLogSource(file,outer);expect(readErrorPagesThenBrowserLogPredecessor(resolve(root,file),'utf8')).toBe(browser);expect(readErrorPagesThenBrowserLogThenConfigClassPredecessor(resolve(root,file),'utf8')).toBe(reverseConfigClassSource(file,browser));const row=configClassSourceBinding.sources.find(row=>row.file===file)!;expect(sha(readErrorPagesThenBrowserLogThenConfigClassPredecessor(resolve(root,file)))).toBe(row.before_sha256);}expect(reverseErrorPagesSource('other.ts','unaltered')).toBe('unaltered');});
 it('preserves fixed original exception copy and public standalone route decisions',()=>{const router=read('view/admin-ts/src/router/index.ts');for(const kind of ['403','404','500','other']){expect(router).toContain('path: "/'+kind+'"');expect(router).toContain('alias: "/admin/'+kind+'"');}expect(router).toContain('exceptionPage: true');expect(router).toContain('if (to.meta.exceptionPage === true || previewMode) return true;');expect(router).toContain('name: "not-found"');expect(proof.boundaries.scope).toContain('not rewritten');const page=read('view/admin-ts/src/pages/system/ExceptionPage.vue');expect(page).not.toContain('route.query');expect(page).not.toContain('route.params');expect(page).not.toContain('v-html');});
 it('keeps the actual exception runtime test in the Admin CI chain',()=>{const script=JSON.parse(read('view/admin-ts/package.json')).scripts['test:exceptions'];expect(script).toContain('--test-concurrency=1');expect(script).toContain('exception-page-runtime.test.cjs');expect(read('.github/workflows/workers-runtime-linux.yml')).toContain('npm run test:exceptions');expect(read('workers-ts/vitest.config.ts')).toContain('test/*.test.ts');});
});

