      ]) },
      { matches: isAdminDeliveryRecoveryRoute, expected: prefixes.flatMap(prefix => [
        pair("GET", `${prefix}/order/delivery/author/receipt/:operationId`), pair("POST", `${prefix}/order/delivery/author/resolve`),
      ]) },
